import { ClaimCells } from '../../slots/defs/claimColumns';
import type { Claim } from './claimsQuery';

/** Whether the claim was added while its period was soft-closed. */
function ClaimLateEntry({ claim }: { sheetId: string; claim: Claim }) {
  return <td data-testid="claim-late-entry">{claim.lateEntry ? 'yes' : 'no'}</td>;
}

export const contribution = ClaimCells.fill({ order: 16, Component: ClaimLateEntry });
import { useQuery } from '@tanstack/react-query';
import { SheetPanel } from '../../slots/defs/sheetPanel';
import { claimsQuery, isActive } from '../claims/claimsQuery';
import type { Claim, ClaimStatus } from '../claims/claimsQuery';
import { GRADES, gradeOn, peopleQuery } from '../people/peopleQuery';
import { classicPeriodDue, periodDue, periodsQuery } from '../periods/periodsQuery';
import { difference, personDue, ratesQuery, sumDue } from '../rates/ratesQuery';
import { useCap, useFloor, useLate } from '../settings/settingsQuery';
import { useSheetToday } from '../sheet/useSheetToday';
import { voidReasonsQuery } from '../voidReasons/voidReasonsQuery';

export const STATUSES: ClaimStatus[] = ['DRAFT', 'OPEN', 'PENDING', 'SETTLED', 'VOID', 'REVIEW'];

/** How many of the sheet's claims have the status. */
export const statusCount = (claims: Claim[], status: ClaimStatus) => claims.filter((c) => c.status === status).length;

/**
 * The sheet at a glance, worked out from the same figures the lists show. Per grade: the people on it
 * today (retired people excluded), their due-totals added up, skipping n/a, and how many of them are active. Per period: its
 * due-total, and its change from the period before it by from-date (none for the earliest). Per status: how many claims have it. Per void reason on the list: how many VOID claims were voided with it.
 */
function Summary({ sheetId }: { sheetId: string }) {
  const people = useQuery(peopleQuery(sheetId)).data ?? [];
  const claims = useQuery(claimsQuery(sheetId)).data ?? [];
  const rates = useQuery(ratesQuery(sheetId)).data ?? [];
  const periods = useQuery(periodsQuery(sheetId)).data ?? [];
  const voidReasons = useQuery(voidReasonsQuery(sheetId)).data ?? [];
  const today = useSheetToday(sheetId);
  const floor = useFloor(sheetId);
  const late = useLate(sheetId);
  const cap = useCap(sheetId);

  const unretired = people.filter((p) => p.retiredFrom === null);
  const byFrom = [...periods].sort((a, b) => (a.from < b.from ? -1 : a.from > b.from ? 1 : 0));
  const dues = new Map(byFrom.map((p) => [p.name, periodDue(p, claims, people, rates, floor, late)]));
  const periodRows = periods.map((p) => {
    const at = byFrom.indexOf(p);
    const due = dues.get(p.name) as string;
    return { period: p, due, change: at > 0 ? difference(due, dues.get(byFrom[at - 1].name) as string) : '' };
  });

  return (
    <section data-testid="summary">
      <h3>Summary</h3>
      <table data-testid="summary-grades">
        <thead>
          <tr>
            <th>Grade</th>
            <th>People</th>
            <th>Due</th>
            <th>Active</th>
          </tr>
        </thead>
        <tbody>
          {GRADES.map((g) => {
            const onGrade = unretired.filter((p) => gradeOn(p, today) === g);
            return (
              <tr key={g} data-testid={`summary-grade-${g}`}>
                <td>{g}</td>
                <td data-testid={`summary-grade-${g}-count`}>{onGrade.length}</td>
                <td data-testid={`summary-grade-${g}-due-total`}>
                  {sumDue(onGrade.map((p) => personDue(p, people, claims, rates, today, floor, late, cap)))}
                </td>
                <td data-testid={`summary-grade-${g}-active`}>
                  {onGrade.filter((p) => isActive(p.id, claims, people, today)).length}
                </td>
              </tr>
            );
          })}
        </tbody>
      </table>
      <table data-testid="summary-periods">
        <thead>
          <tr>
            <th>Period</th>
            <th>Due</th>
            <th>Change</th>
          </tr>
        </thead>
        <tbody>
          {periodRows.map(({ period: p, due, change }) => (
            <tr key={p.name} data-testid={`summary-period-${p.name}`}>
              <td>{p.name}</td>
              <td data-testid={`summary-period-${p.name}-due-total`}>{due}</td>
              <td data-testid={`summary-period-${p.name}-change`}>{change}</td>
            </tr>
          ))}
        </tbody>
      </table>
      <table data-testid="summary-statuses">
        <thead>
          <tr>
            <th>Status</th>
            <th>Claims</th>
          </tr>
        </thead>
        <tbody>
          {STATUSES.map((s) => (
            <tr key={s} data-testid={`summary-status-${s}`}>
              <td>{s}</td>
              <td data-testid={`summary-status-${s}-count`}>{statusCount(claims, s)}</td>
            </tr>
          ))}
        </tbody>
      </table>
      <table data-testid="summary-void-reasons">
        <thead>
          <tr>
            <th>Void reason</th>
            <th>Claims</th>
          </tr>
        </thead>
        <tbody>
          {voidReasons.map((r) => (
            <tr key={r.reason} data-testid={`summary-void-${r.reason}`}>
              <td>{r.reason}</td>
              <td data-testid={`summary-void-${r.reason}-count`}>{r.voided}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </section>
  );
}

/**
 * The classic summary, beside the summary: per period, its due-total counting each claim by its status now (a closed
 * period shows the figure fixed when it closed), and the sheet's due-total with no trimming (everyone's added up).
 */
function ClassicSummary({ sheetId }: { sheetId: string }) {
  const people = useQuery(peopleQuery(sheetId)).data ?? [];
  const claims = useQuery(claimsQuery(sheetId)).data ?? [];
  const rates = useQuery(ratesQuery(sheetId)).data ?? [];
  const periods = useQuery(periodsQuery(sheetId)).data ?? [];
  const today = useSheetToday(sheetId);
  const floor = useFloor(sheetId);
  const late = useLate(sheetId);
  const cap = useCap(sheetId);

  return (
    <section data-testid="classic-summary">
      <h3>Classic summary</h3>
      <table data-testid="classic-periods">
        <thead>
          <tr>
            <th>Period</th>
            <th>Due</th>
          </tr>
        </thead>
        <tbody>
          {periods.map((p) => (
            <tr key={p.name} data-testid={`classic-period-${p.name}`}>
              <td>{p.name}</td>
              <td data-testid={`classic-period-${p.name}-due-total`}>{classicPeriodDue(p, claims, people, rates, floor, late)}</td>
            </tr>
          ))}
        </tbody>
      </table>
      <p>
        Due <strong data-testid="classic-due-total">{sumDue(people.map((p) => personDue(p, people, claims, rates, today, floor, late, cap)))}</strong>
      </p>
    </section>
  );
}

export const contributions = [
  SheetPanel.fill({ order: 30, Component: Summary }),
  SheetPanel.fill({ order: 31, Component: ClassicSummary }),
];
import { getJson } from '../../api/http';
import { heldOn, type Person } from '../people/peopleQuery';
import { sheetKey } from '../sheet/sheetQuery';

/** REVIEW: opened with a due above the review threshold in force on its date; unnumbered and counting in no total until a steward's review makes it OPEN. */
export type ClaimStatus = 'DRAFT' | 'OPEN' | 'PENDING' | 'SETTLED' | 'VOID' | 'DELETED' | 'REVIEW';

/** An open claim: OPEN, or PENDING (settled by a clerk above the clerk limit, awaiting a steward), handled like OPEN in every total. */
export const isOpen = (c: Claim) => c.status === 'OPEN' || c.status === 'PENDING';

/**
 * `amount` has two decimals ("12.50"); `date` is yyyy-mm-dd; `number` is given on opening and kept when voided (null for a draft);
 * `settledDue` is the due fixed on settling (null when not settled, or settled while no rate applied on the claim's date);
 * `openedBy` is the user who opened it (null when never opened), who cannot settle it;
 * `stated` is whether its person's last statement bound it, at `statedDue` (null when it had no figure then) — a PENDING claim is not bound while PENDING;
 * a negative `amount` is a correction, and `corrects` is the number of the settled claim it corrects (null for any other claim);
 * `dueBy` (yyyy-mm-dd) is fixed when the claim is made, from its person's own terms, else the terms of their grade on its date, counted in business days after its date (skipping Saturdays, Sundays and the sheet's holidays as they then were), and kept when they or its date change;
 * `log` is its status log, oldest first, one line per status it has had: "<STATUS> by <user> on <date> due=<due>";
 * `deferredUntil` (yyyy-mm-dd) is the date an OPEN claim was deferred to (null when never deferred), see `isDeferred`;
 * `proofs` is how many proofs it has been given: one above the sheet's proof threshold is settled or approved only with one;
 * `splitFrom` is the number of the claim it was split off (null for any other claim);
 * `lockedBy` is the user whose open editor locks it for everyone else (null when not locked);
 * `lateEntry` is whether it was added while the period its due-by falls in was soft-closed;
 * `remindedOn` (yyyy-mm-dd) is the last sheet's today a reminder was written for it (null when never reminded);
 * `ref` is its external reference, unique on the sheet without regard to case (null when it has none);
 * `tags` are its tags, trimmed, lower-cased, without repeats and sorted (empty for none);
 * `comments` are its comments, oldest first, each "<user> on <date>: <text>" with the sheet's today when written;
 * `batch` is the number of the settle batch (a bulk settle) that settled it (null when none, or settled one at a time);
 * `lines` are its lines, in the order added, each "<label> <qty> x <unit>" (a DRAFT's amount is then their sum).
 */
export type Claim = {
  id: number;
  personId: number;
  amount: string;
  date: string;
  note: string;
  status: ClaimStatus;
  number: string | null;
  settledDue: string | null;
  openedBy: string | null;
  stated: boolean;
  statedDue: string | null;
  corrects: string | null;
  dueBy: string;
  log: string[];
  deferredUntil: string | null;
  proofs: number;
  splitFrom: string | null;
  lockedBy: string | null;
  lateEntry: boolean;
  remindedOn: string | null;
  ref: string | null;
  tags: string[];
  comments: string[];
  batch: number | null;
  lines: string[];
};

/** A correction: its due is its amount times the rate, with no floor and no late charge. */
export const isCorrection = (c: Claim) => Number(c.amount) < 0;

/**
 * An OPEN claim deferred to a date the sheet's `today` has not reached: it counts in no total, is not overdue and
 * cannot be settled. From that day on it is an OPEN claim like any other.
 */
export const isDeferred = (c: Claim, today: string) =>
  c.status === 'OPEN' && c.deferredUntil !== null && (today === '' || today < c.deferredUntil);

/**
 * Only open (OPEN or PENDING) and SETTLED claims count toward claimed, due and every total; drafts, voided and
 * deleted ones do not, nor do a person's open claims dated within one of their holds, or once the sheet's `today` reaches
 * their retirement date, unless a statement bound them, nor an OPEN claim deferred on the sheet's `today`.
 */
export const counts = (c: Claim, people: Person[], today: string) =>
  !isDeferred(c, today) &&
  (c.status === 'SETTLED' ||
  (isOpen(c) &&
    ((c.stated && c.status !== 'PENDING') || !leftOut(people.find((p) => p.id === c.personId), c.date, today))));

/** Whether the person's unbound open claim dated `date` is left out: within a hold, or retired by `today`. */
import { useQuery } from '@tanstack/react-query';
import { sheetQuery } from './sheetQuery';

/** The sheet's today (yyyy-mm-dd), or '' until loaded. Every default date uses this, never `new Date()`. */
export function useSheetToday(sheetId: string): string {
  return useQuery(sheetQuery(sheetId)).data?.today ?? '';
}

