            </tr>
          ))}
        </tbody>
      </table>
      <p>
        Due <strong data-testid="classic-due-total">{sumDue(people.map((p) => personDue(p, people, claims, rates, today, floor, late, cap)))}</strong>
      </p>
    </section>
  );
}

